import unittest

from solucao import apagar
from solucao import apagar_e_contar


class TestApagarUmaChave(unittest.TestCase):
    def test_apaga_a_chave_pedida(self):
        """apagar tira a chave pedida do dicionario"""
        d = {"a": 1, "b": 2}
        apagar(d, "a")
        self.assertEqual(d, {"b": 2})

    def test_apagar_esvazia_o_dicionario(self):
        """apagar a unica chave esvazia o dicionario"""
        d = {"x": 7}
        apagar(d, "x")
        self.assertEqual(d, {})

    def test_conta_as_chaves_que_sobram(self):
        """apagar_e_contar devolve quantas chaves sobraram depois de apagar"""
        d = {"a": 1, "b": 2, "c": 3}
        self.assertEqual(apagar_e_contar(d, "a"), 2)

    def test_conta_zero_com_a_ultima_chave(self):
        """apagar_e_contar devolve zero quando so restava a chave apagada"""
        d = {"x": 7}
        self.assertEqual(apagar_e_contar(d, "x"), 0)

